/* AutoPromote - Modern Styling */
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html,
body,
#root,
.App {
  width: 100%;
  max-width: 100%;
  min-width: 0;
}

html,
body {
  overflow-x: hidden;
  overscroll-behavior-x: none;
}

img,
video,
canvas {
  max-width: 100%;
}

body {
  font-family: "Segoe UI", Tahoma, Geneva, Verdana, sans-serif;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  min-height: 100vh;
  color: #333;
}

@media (max-width: 1023px) {
  .App {
    overflow-x: hidden;
  }

  .App main,
  .App section,
  .App article,
  .App form,
  .App fieldset,
  .App [role="dialog"] {
    min-width: 0;
    max-width: 100%;
  }

  .App input:not([type="checkbox"]):not([type="radio"]),
  .App select,
  .App textarea {
    max-width: 100%;
    font-size: 16px;
  }

  .App h1,
  .App h2,
  .App h3,
  .App p,
  .App a,
  .App td,
  .App th,
  .App label,
  .App span {
    overflow-wrap: anywhere;
  }

  .ap-page-container,
  .ap-landing-page {
    width: 100%;
    max-width: 100%;
    padding-left: max(0.85rem, env(safe-area-inset-left));
    padding-right: max(0.85rem, env(safe-area-inset-right));
    overflow-x: hidden;
  }

  .ap-features-grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .ap-content-section,
  .ap-feature-card {
    min-width: 0;
    padding: clamp(1rem, 5vw, 1.5rem);
  }

  .modal-overlay.open {
    width: 100%;
    max-width: 100%;
    overflow-x: hidden;
    overflow-y: auto;
    overscroll-behavior: contain;
    -webkit-overflow-scrolling: touch;
  }

  .modal-overlay.open > div {
    width: 100%;
    min-width: 0;
    max-width: 100%;
  }

  .table-container,
  .team-table-wrap {
    max-width: 100%;
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
  }
}

/* modal overlay defaults (used by login/register modals)
   Keep overlays inert by default so incidental wrappers don't block content.
   Components should toggle `.open` when the overlay is active. */
.modal-overlay {
  background: transparent;
  position: fixed;
  inset: 0;
  z-index: 2000;
  display: flex;
  justify-content: center;
  align-items: center;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  pointer-events: none;
}

/* When explicitly opened, show the backdrop and allow interaction */
.modal-overlay.open {
  background: rgba(0, 0, 0, 0.45) !important;
  -webkit-backdrop-filter: blur(5px);
          backdrop-filter: blur(5px);
  pointer-events: auto;
}

/* When on dashboard, avoid showing purple/blue modal overlays and body background */
html.dashboard-mode,
body.dashboard-mode {
  background: #000 !important;
  background-image: none !important;
}
html.dashboard-mode .modal-overlay,
body.dashboard-mode .modal-overlay {
  background: rgba(0, 0, 0, 0.45) !important;
  background-image: none !important;
}

/* global body class to suppress scrolling when a modal is active */
body.modal-open {
  overflow: hidden !important;
  overscroll-behavior: none;
  touch-action: pan-y pinch-zoom;
}

