/* Welcome Section */
.WelcomeSection {
  text-align: center;
  color: white;
  padding: 6rem 2rem;
  position: relative;
  overflow: hidden;
  background: linear-gradient(135deg, rgba(102, 126, 234, 0.9) 0%, rgba(118, 75, 162, 0.9) 100%);
  border-radius: 20px;
  margin: 2rem auto;
  max-width: 800px;
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.3);
  animation: slideInUp 1s ease-out;
  filter: drop-shadow(0 0 10px rgba(118, 75, 162, 0.7));
}

.WelcomeSection::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: url("data:image/svg+xml,<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 100 100\"><circle cx=\"20\" cy=\"20\" r=\"2\" fill=\"rgba%28255,255,255,0.1%29\"/><circle cx=\"80\" cy=\"40\" r=\"1.5\" fill=\"rgba%28255,255,255,0.1%29\"/><circle cx=\"40\" cy=\"80\" r=\"1\" fill=\"rgba%28255,255,255,0.1%29\"/><circle cx=\"60\" cy=\"10\" r=\"1.5\" fill=\"rgba%28255,255,255,0.1%29\"/><circle cx=\"90\" cy=\"70\" r=\"2\" fill=\"rgba%28255,255,255,0.1%29\"/></svg>");
  opacity: 0.5;
  animation: float 6s ease-in-out infinite;
  filter: drop-shadow(0 0 5px rgba(255, 255, 255, 0.3));
}

.WelcomeSection h2 {
  font-size: 3.5rem;
  margin-bottom: 1.5rem;
  background: linear-gradient(45deg, #ffffff, #e0e7ff);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  text-shadow: 0 0 30px rgba(255, 255, 255, 0.5);
  position: relative;
  z-index: 2;
  animation: glow 2s ease-in-out infinite alternate;
  text-transform: uppercase;
  letter-spacing: 2px;
  filter: drop-shadow(0 0 10px rgba(255, 255, 255, 0.7));
}

.WelcomeSection h2::before {
  content: "🚀";
  position: absolute;
  left: -50px;
  top: 50%;
  transform: translateY(-50%);
  font-size: 2.5rem;
  animation: bounce 1s ease-in-out infinite;
  filter: drop-shadow(0 0 5px rgba(255, 255, 255, 0.8));
}

.WelcomeSection p {
  font-size: 1.6rem;
  margin-bottom: 3rem;
  opacity: 0.95;
  position: relative;
  z-index: 2;
  line-height: 1.6;
  font-weight: 600;
  text-shadow: 0 0 10px rgba(0, 0, 0, 0.2);
}

.WelcomeSection p::after {
  content: "✨";
  position: absolute;
  right: -30px;
  top: 50%;
  transform: translateY(-50%);
  font-size: 1.8rem;
  animation: sparkle 2s ease-in-out infinite;
  filter: drop-shadow(0 0 5px rgba(255, 255, 255, 0.8));
}

.WelcomeSection button {
  background: linear-gradient(135deg, rgba(255, 255, 255, 0.4) 0%, rgba(255, 255, 255, 0.15) 100%);
  color: white;
  border: 2px solid rgba(255, 255, 255, 0.9);
  padding: 1.4rem 3.5rem;
  border-radius: 50px;
  font-size: 1.3rem;
  font-weight: 800;
  cursor: pointer;
  -webkit-backdrop-filter: blur(25px);
          backdrop-filter: blur(25px);
  transition: all 0.5s ease;
  position: relative;
  z-index: 2;
  text-transform: uppercase;
  letter-spacing: 2px;
  box-shadow: 0 10px 40px rgba(255, 255, 255, 0.15);
  filter: drop-shadow(0 0 10px rgba(255, 255, 255, 0.5));
}

.WelcomeSection button:hover {
  background: white;
  color: #667eea;
  transform: translateY(-6px) scale(1.1);
  box-shadow: 0 20px 50px rgba(255, 255, 255, 0.6);
  border-color: white;
}

.WelcomeSection button::before {
  content: "";
  position: absolute;
  top: 0;
  left: -100%;
  width: 100%;
  height: 100%;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.5), transparent);
  transition: left 0.5s;
}

.WelcomeSection button:hover::before {
  left: 100%;
}

/* Animations */
@keyframes slideInUp {
  from {
    opacity: 0;
    transform: translateY(50px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes glow {
  from {
    text-shadow: 0 0 20px rgba(255, 255, 255, 0.5);
  }
  to {
    text-shadow:
      0 0 40px rgba(255, 255, 255, 0.8),
      0 0 60px rgba(255, 255, 255, 0.6);
  }
}

@keyframes bounce {
  0%,
  20%,
  50%,
  80%,
  100% {
    transform: translateY(-50%) translateX(0);
  }
  40% {
    transform: translateY(-50%) translateX(-10px);
  }
  60% {
    transform: translateY(-50%) translateX(-5px);
  }
}

@keyframes sparkle {
  0%,
  100% {
    opacity: 0.5;
    transform: translateY(-50%) scale(1);
  }
  50% {
    opacity: 1;
    transform: translateY(-50%) scale(1.2);
  }
}

@keyframes float {
  0%,
  100% {
    transform: translateY(0px);
  }
  50% {
    transform: translateY(-10px);
  }
}

