/* Mobile Fixes for Content Upload and TikTok Options */
@media (max-width: 768px) {
  form {
    padding: 1rem;
    width: 95%;
    margin: 1rem auto;
    overflow-x: hidden; /* Prevent horizontal scroll on form body */
  }

  .tiktok-options {
    max-width: 100%;
    overflow-x: hidden;
  }

  /* Fix text overflow in disclosure boxes */
  .tiktok-options .no-video-disclosure,
  .tiktok-options div[role="status"],
  .tiktok-options div {
    white-space: normal !important;
    word-break: break-word !important;
    overflow-wrap: break-word !important;
    max-width: 100%;
    box-sizing: border-box;
  }

  /* Fix for invisible/black checkboxes on mobile */
  .tiktok-options input[type="checkbox"] {
    appearance: checkbox !important;
    width: 20px !important;
    height: 20px !important;
    background: #fff !important;
    border: 1px solid #ccc !important;
    margin-right: 8px;
    display: inline-block;
    flex-shrink: 0;
  }

  /* Ensure labels align nicely */
  .tiktok-options label {
    display: flex;
    align-items: center;
    font-size: 0.9rem;
    line-height: 1.4;
    white-space: normal;
  }
}

