}
.twitter-form {
  border-left: 5px solid #1da1f2;
}
.pinterest-form {
  border-left: 5px solid #e60023;
}
.reddit-form {
  border-left: 5px solid #ff4500;
}
.spotify-form {
  border-left: 5px solid #1db954;
}

.platform-form-header {
  font-size: 1.25rem;
  font-weight: 700;
  color: #1a202c;
  margin-bottom: 20px;
  padding-bottom: 12px;
  border-bottom: 2px solid #edf2f7;
  display: flex;
  align-items: center;
  gap: 10px;
}

.form-group-modern {
  margin-bottom: 20px;
}

.form-group-modern label {
  display: block;
  font-weight: 600;
  color: #2d3748;
  margin-bottom: 8px;
  font-size: 0.95rem;
}

.modern-input,
.modern-textarea,
.modern-select {
  width: 100%;
  max-width: 100%;
  box-sizing: border-box;
  padding: 12px 16px;
  border: 2px solid #e2e8f0;
  border-radius: 8px;
  font-size: 1rem;
  transition: all 0.2s ease;
  background-color: #f8fafc;
  color: #1a202c;
}

.modern-input:focus,
.modern-textarea:focus,
.modern-select:focus {
  border-color: #667eea;
  background-color: white;
  outline: none;
  box-shadow: 0 0 0 3px rgba(102, 126, 234, 0.1);
}

.modern-textarea {
  min-height: 120px;
  resize: vertical;
}

.modern-helper-text {
  display: block;
  margin-top: 6px;
  font-size: 0.85rem;
  color: #718096;
}

.checkbox-group-modern {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 0;
}

.checkbox-group-modern input[type="checkbox"] {
  width: 18px;
  height: 18px;
  accent-color: #667eea;
}

.checkbox-group-modern label {
  margin-bottom: 0;
  cursor: pointer;
}

/* Additional strong mobile overrides to ensure modal and forms are fully visible */
@media (max-width: 760px) {
  .platform-form {
    padding: 16px;
    margin-bottom: 16px;
  }

  .modal-overlay {
    align-items: flex-start !important;
    padding-top: 12px !important;
    padding-bottom: calc(env(safe-area-inset-bottom, 0) + 120px) !important;
    touch-action: pan-y !important;
    background: transparent !important;
    pointer-events: none !important;
  }

  .modal-overlay .modal,
  .modal-overlay .publish-panel,
  .modal-overlay .publish-modal,
  .modal-overlay .PublishPanel {
    pointer-events: auto !important;
    position: relative !important;
    inset: auto !important;
    /* limit the modal to the dashboard's mobile container width so the dark
       card behind it lines up exactly; also still respect a viewport margin */
    width: auto !important;
    max-width: min(calc(100% - 32px), 420px) !important;
    margin: 8px auto !important;
    max-height: calc(100vh - 160px) !important;
    overflow-y: auto !important;
    -webkit-overflow-scrolling: touch !important;
    box-sizing: border-box !important;
    border-radius: 12px !important;
    background: #ffffff !important;
    background: var(--surface, #ffffff) !important;
  }

  .modal-overlay form,
  .publish-panel form,
  .PublishPanel form {
    max-width: 100% !important;
    width: 100% !important;
    margin: 0 !important;
    box-shadow: none !important;
    border-radius: 8px !important;
  }

  .modal-overlay.open {
    background: rgba(0, 0, 0, 0.4) !important;
    pointer-events: auto !important;
  }
}

/* PayPalSubscriptionPanel.css */

.paypal-subscription-panel {
  padding: 20px;
  max-width: 1400px;
  margin: 0 auto;
}

.paypal-subscription-panel.compact {
  padding: 0;
  max-width: none;
  width: 100%;
  min-width: 0;
}

.paypal-subscription-panel.compact .paypal-subscription-panel-header {
  margin-bottom: 18px;
}

.paypal-subscription-panel.compact .paypal-subscription-panel-subtitle {
  margin-bottom: 0;
}

.paypal-subscription-panel-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
}

.paypal-subscription-panel-subtitle {
  margin: 0.5rem 0 1.25rem;
  color: #4b5563;
  max-width: 760px;
  line-height: 1.55;
}

.subscription-panel-close {
  border: 1px solid rgba(15, 23, 42, 0.12);
  background: rgba(15, 23, 42, 0.08);
  color: #0f172a;
  min-height: 40px;
  border-radius: 999px;
  cursor: pointer;
  font-size: 14px;
  font-weight: 800;
  line-height: 1;
  white-space: nowrap;
  padding: 0 16px;
  transition:
    transform 0.18s ease,
    background 0.18s ease,
    border-color 0.18s ease;
}

.subscription-panel-close:hover {
  background: rgba(15, 23, 42, 0.13);
  border-color: rgba(15, 23, 42, 0.2);
  transform: translateY(-1px);
}

.subscription-panel-close.is-compact {
  width: 40px;
  padding: 0;
  font-size: 24px;
}

.subscription-panel-close.is-return::before {
  content: "←";
  margin-right: 8px;
}

.paypal-sdk-notice {
  margin: 0 0 18px;
  padding: 12px 14px;
  border-radius: 12px;
  font-size: 14px;
  line-height: 1.5;
}

.paypal-sdk-notice.neutral {
  background: #eff6ff;
  border: 1px solid #bfdbfe;
  color: #1d4ed8;
}

.paypal-sdk-notice.warning {
  background: #fff7ed;
  border: 1px solid #fdba74;
  color: #9a3412;
}

.paypal-subscription-panel h2 {
  font-size: 28px;
  margin-bottom: 24px;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* Current Subscription Card */
