/* The normal-motion hero is a real Three.js scene. CSS styles its DOM controls. */
html:has(.lp-page),
body:has(.lp-page) {
  overflow-x: clip;
  overflow-y: visible;
}
.App:has(.lp-page) {
  overflow: clip;
}
.lp-hero {
  grid-template-columns: 0.75fr 1.25fr;
}
.lp-motion-scene {
  min-width: 0;
