  height: 100%;
  opacity: 0;
  transition: opacity 450ms;
}
.lp-motion-scene.is-ready .lp-motion-canvas {
  opacity: 1;
}
.lp-motion-fallback {
  position: absolute;
  inset: 0;
  pointer-events: none;
}
.lp-motion-fallback .lp-editor-scene {
  height: 100%;
  width: 100%;
  margin: 0;
  transform: scale(0.9);
