/* Motion graphics are a visual layer. Real navigation and auth controls stay HTML. */
.lp-title-matte {
  display: block;
  overflow: clip;
  padding: 0.08em 0 0.08em 0.03em;
  margin: -0.08em 0 -0.08em -0.03em;
}
.lp-title-matte > span {
  display: inline-block;
  transform-origin: 15% 80%;
}
.lp-kinetic-title .lp-gradient-text {
  background-size: 180% 100%;
}
.lp-motion-surface {
  isolation: isolate;
}
.lp-motion-canvas {
  position: relative;
  z-index: 1;
}
.lp-motion-fallback {
  z-index: 1;
}
.lp-motion-graphics {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 1;
}
.lp-motion-graphics[data-enabled="false"] {
  display: none;
}
.lp-graphic-word-mask {
  position: absolute;
  top: 20px;
  left: 24px;
  right: 24px;
  overflow: clip;
  color: #b9adce;
  font-size: 11px;
  line-height: 1.4;
  letter-spacing: 0.16em;
  font-weight: 600;
}
.lp-graphic-word-mask > span {
  display: block;
  white-space: nowrap;
  transform: translateX(calc((1 - 0) * -50px));
  transform: translateX(calc((1 - var(--graphic-reveal, 0)) * -50px));
  clip-path: inset(0 calc((1 - 0) * 100%) 0 0);
  clip-path: inset(0 calc((1 - var(--graphic-reveal, 0)) * 100%) 0 0);
}
.lp-graphic-light-sweep {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 18%;
  height: 1px;
  background: linear-gradient(90deg, transparent, #aa6cec55, #82d9ee66, transparent);
  transform: scaleX(0);
  transform: scaleX(var(--graphic-sweep, 0));
  transform-origin: left;
}
.lp-graphic-progress {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 1px;
  background: linear-gradient(90deg, #a182ed, #69cdd7);
  transform: scaleX(0);
  transform: scaleX(var(--film-progress, 0));
  transform-origin: left;
}
.lp-composition-marks {
  position: absolute;
  inset: 4% 0;
  width: 100%;
  height: 92%;
}
.lp-composition-marks path {
  stroke: #a783ca1a;
  stroke-width: 0.9;
}
.lp-motion-stroke {
  stroke-dasharray: 70;
  stroke-dashoffset: calc((1 - 0) * 70);
  stroke-dashoffset: calc((1 - var(--graphic-reveal, 0)) * 70);
}
.lp-authored-motion {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0;
  z-index: 3;
}
.lp-authored-motion > video,
.lp-authored-motion > img,
.lp-authored-motion > svg {
  width: 100%;
  height: 100%;
  object-fit: contain;
}
.lp-authored-brand-reveal {
  inset: 14% 10%;
}
.lp-story-title-matte {
  overflow: clip;
}
.lp-story-title-matte > span {
  display: block;
  animation: lp-chapter-matte 480ms cubic-bezier(0.16, 1, 0.3, 1) both;
}
@keyframes lp-chapter-matte {
  from {
    transform: translateY(34px);
    clip-path: inset(0 0 100%);
    filter: blur(4px);
  }
  to {
    transform: translateY(0);
    clip-path: inset(0);
    filter: blur(0);
  }
