/* Responsive, modern dashboard styles */
:root {
  --bg: #0b1220;
  --bg-2: #0e162a;
  --card: #121a2c;
  --muted: #9aa4b2;
  --text: #eef2ff;
  --brand: #6d28d9;
  --brand-2: #8b5cf6;
  --ring: rgba(139, 92, 246, 0.35);
  --border: rgba(255, 255, 255, 0.08);
}

/*
  Scrollbar, selection and overscroll styling
  - Forces dark/black scrollbars inside dashboard so OS accent color (blue) doesn't show
  - Adds overscroll-behavior to prevent glow/overscroll color on some platforms
  - Adjusts selection color inside dashboard to dark to avoid the default blue highlight
*/
.dashboard-root {
  /* Keep horizontal overscroll contained, but let vertical wheel/touch gestures
     reach the document scroller. `contain` here made narrow dashboard pages
     look scrollable while swallowing the user's actual scroll gesture. */
  overscroll-behavior-x: contain;
  overscroll-behavior-y: auto;
}

/* Firefox */
.dashboard-root,
.dashboard-root * {
  scrollbar-width: thin;
  scrollbar-color: #000000 rgba(255, 255, 255, 0.03);
}

/* WebKit (Chrome, Edge, Safari) */
.dashboard-root ::-webkit-scrollbar {
  height: 10px;
  width: 10px;
}
.dashboard-root ::-webkit-scrollbar-track {
  background: #000; /* pure black track */
}
.dashboard-root ::-webkit-scrollbar-thumb {
  background-color: #000; /* black thumb */
  border-radius: 10px;
  border: 2px solid transparent; /* keeps the thumb from blending with the track */
}
.dashboard-root ::-webkit-scrollbar-thumb:hover {
  background-color: #222;
}

/* Avoid blue text selection highlight on the dashboard */
.dashboard-root ::selection {
  background: #000;
  color: #eef2ff;
  color: var(--text);
}

/* Prevent horizontal overflow and ensure body background doesn't show through on dashboard pages */
/* Ensure dashboard pages have a black background behind any translucent elements, while allowing component-level horizontal scroll
   so wide tables or card lists still scroll inside the dashboard without revealing the app's blue gradient. */
html.dashboard-mode,
body.dashboard-mode {
  background: #000 !important; /* All black background */
  background-image: none !important; /* Remove any previously defined gradient or image */
  background-color: #000 !important;
  color-scheme: dark;
  min-height: 100%;
  overflow-x: clip;
  overflow-y: auto;
  overscroll-behavior-y: auto;
  -webkit-overflow-scrolling: touch;
}

body.dashboard-mode:not(.modal-open) {
  overflow-y: auto !important;
  touch-action: pan-y pinch-zoom;
}

/* Ensure OS/Browser scrollbars are dark across the entire page in dashboard mode */
html.dashboard-mode,
body.dashboard-mode,
html.dashboard-mode *,
body.dashboard-mode * {
  scrollbar-width: thin;
  scrollbar-color: #000000 rgba(255, 255, 255, 0.03);
}
html.dashboard-mode ::-webkit-scrollbar,
body.dashboard-mode ::-webkit-scrollbar {
  width: 10px;
  height: 10px;
}
html.dashboard-mode ::-webkit-scrollbar-track,
body.dashboard-mode ::-webkit-scrollbar-track {
  background: #000;
}
html.dashboard-mode ::-webkit-scrollbar-thumb,
body.dashboard-mode ::-webkit-scrollbar-thumb {
  background-color: #000;
  border-radius: 10px;
  border: 2px solid transparent;
}
html.dashboard-mode ::-webkit-scrollbar-thumb:hover,
body.dashboard-mode ::-webkit-scrollbar-thumb:hover {
  background-color: #111;
}

/* Root */
.dashboard-root {
  min-height: 100vh;
  min-height: 100dvh;
  /* Use a pure dark background for the dashboard to avoid overlay gradients */
  background: #000;
  color: #eef2ff;
  color: var(--text);
  font-family:
    Inter,
    system-ui,
    -apple-system,
    Segoe UI,
    Roboto,
    Arial,
    sans-serif;
  /* Prevent the entire page from horizontally scrolling which causes content
     to slide under the fixed sidebar. Keep horizontal scrolling inside the
     dashboard main area so wide tables/cards scroll within the content pane. */
  overflow-x: clip;
  overflow-y: visible;
  /* Reserve space for the fixed topbar so page content doesn't sit under it */
  padding-top: 64px;
}

/* Topbar */
.dashboard-topbar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 60;
  display: flex;
  align-items: center;
  gap: 0.75rem;
  box-sizing: border-box;
  padding: 0.75rem 1rem;
  background: #07101f;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  border-bottom: 1px solid var(--border);
  box-shadow: 0 10px 24px rgba(0, 0, 0, 0.26);
}
.dashboard-topbar .hamburger {
  width: 40px;
  height: 40px;
  display: inline-flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 3px;
  border-radius: 10px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border: 1px solid var(--border);
  background: #111c31;
  color: #eef2ff;
  color: var(--text);
  cursor: pointer;
}
.dashboard-topbar .hamburger span {
  width: 18px;
  height: 2px;
  background: #eef2ff;
  background: var(--text);
  display: block;
}
.dashboard-topbar .topbar-title {
  min-width: 0;
  font-weight: 700;
  letter-spacing: 0.2px;
  line-height: 1.1;
}
.dashboard-topbar .topbar-user {
  min-width: 0;
  margin-left: auto;
  color: #9aa4b2;
  color: var(--muted);
  font-weight: 600;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* Layout */
.dashboard-sidebar {
  position: fixed;
  top: 60px;
  left: 0;
  bottom: 0;
  width: 280px;
  box-sizing: border-box;
  background: #08111f;
  border-right: 1px solid rgba(255, 255, 255, 0.08);
  border-right: 1px solid var(--border);
  transform: translateX(-100%);
  transition: transform 0.25s ease;
  padding: 1rem 1rem 1.25rem 1rem;
  display: flex;
  flex-direction: column;
  overflow-y: auto;
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
  z-index: 25;
  box-shadow: 18px 0 44px rgba(0, 0, 0, 0.32);
}
.dashboard-sidebar.open {
  transform: translateX(0);
}

.sidebar-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.5);
  z-index: 20;
}

@media (min-width: 1024px) {
  .dashboard-sidebar {
    transform: none;
    top: 64px;
    height: calc(100dvh - 64px);
    overflow-x: hidden;
    overflow-y: auto;
  }
  .sidebar-backdrop {
    display: none;
  }
}

.dashboard-main {
  max-width: 1200px;
  margin: 1rem auto;
  padding: 1rem;
  /* Allow horizontal scroll inside the main content area instead of the
     whole page. This prevents content from being hidden under the fixed
     sidebar when the content is wider than the viewport. */
  overflow-x: auto;
  overflow-y: visible;
  -webkit-overflow-scrolling: touch;
}

/* Mobile centering fixes: ensure dashboard content and forms are centered on small screens */
@media (max-width: 820px) {
  html.dashboard-mode,
  body.dashboard-mode {
    height: auto;
    min-height: 100%;
    overflow-x: clip !important;
    overflow-y: auto !important;
  }

  .dashboard-main {
    margin-left: 0 !important;
    margin-right: 0 !important;
    padding: 0.5rem 0 !important;
    max-width: none !important;
    width: 100% !important;
    box-sizing: border-box !important;
    overflow-x: clip !important;
    overflow-y: visible !important;
    touch-action: pan-y;
  }

  .dashboard-root {
    padding-left: 0 !important;
    padding-right: 0 !important;
    min-height: 100dvh;
    overflow-x: clip !important;
    overflow-y: visible !important;
  }

  .upload-panel,
  .profile-details,
  .analytics-panel {
    margin: 0 auto !important;
    width: 100% !important;
    max-width: none !important;
    box-sizing: border-box !important;
    display: flex !important;
    flex-direction: column !important;
    align-items: stretch !important;
  }

  .upload-panel {
    padding: 0.75rem 12px !important;
    border-radius: 0 !important;
    border-left: none !important;
    border-right: none !important;
  }

  .upload-panel > * {
    width: 100% !important;
    max-width: none !important;
  }

  /* Ensure forms are centered inside panels */
  .upload-panel form,
  .profile-details form,
  .publish-panel form {
    margin: 0 !important;
    width: 100% !important;
    max-width: 100% !important;
    box-sizing: border-box !important;
    position: static !important;
    left: auto !important;
    right: auto !important;
    transform: none !important;
    overflow-x: hidden !important;
    display: flex !important;
    flex-direction: column !important;
    align-items: stretch !important;
  }

  .upload-panel .unified-publisher-container,
  .upload-panel .publisher-layout,
  .upload-panel .platform-workspace,
  .upload-panel .platform-stack,
  .upload-panel .platform-section {
    width: 100% !important;
    max-width: none !important;
  }

  /* platform-form entries should occupy full width to match card background */
  .platform-form,
  .platform-form form {
    width: 100% !important;
    max-width: 100% !important;
    margin-left: 0 !important;
    margin-right: 0 !important;
  }

  .publish-panel .platform-form *,
  .publish-panel .platform-card-wrapper * {
    margin-left: 0 !important;
    margin-left: initial !important;
    margin-right: 0 !important;
    margin-right: initial !important;
  }
}
@media (min-width: 1024px) {
  .dashboard-main {
    /* Reserve space for the fixed sidebar and let the desktop content breathe. */
    margin-left: 300px;
    width: calc(100% - 324px);
    max-width: none;
    margin-right: 24px;
    padding-right: 0;
