/* Main panels */
.profile-details,
.upload-panel,
.analytics-panel,
.rewards-panel,
.notifications-panel {
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.03), rgba(255, 255, 255, 0.02));
  border: 1px solid rgba(255, 255, 255, 0.08);
  border: 1px solid var(--border);
  border-radius: 18px;
  padding: 1rem;
  overflow: visible; /* allow children (like publisher) to overflow/scroll internally */
}
.profile-details h3,
.upload-panel h3,
.analytics-panel h3,
.rewards-panel h3,
.notifications-panel h3 {
  margin: 0 0 0.75rem 0;
}

.landing-preview {
  display: grid;
  grid-template-columns: 120px 1fr;
  grid-gap: 1rem;
  gap: 1rem;
  align-items: start;
}
.landing-thumbnail {
  width: 120px;
  height: 80px;
  border-radius: 10px;
  object-fit: cover;
  background: rgba(255, 255, 255, 0.06);
}
.performance-summary {
  display: flex;
  gap: 1rem;
  color: #9aa4b2;
  color: var(--muted);
  margin-top: 0.5rem;
}

.upload-drag-drop {
  background: rgba(255, 255, 255, 0.05);
  border: 1px dashed rgba(255, 255, 255, 0.15);
  padding: 1rem;
  border-radius: 12px;
  text-align: center;
}
.upload-preview {
  margin-top: 0.6rem;
  border: 1px solid rgba(255, 255, 255, 0.04);
  border-radius: 10px;
  padding: 0.5rem;
  background: rgba(255, 255, 255, 0.02);
}
.upload-preview img,
.upload-preview video {
  width: 100%;
  max-height: 360px;
  border-radius: 8px;
  object-fit: cover;
}
.upload-controls {
  display: flex;
  gap: 0.5rem;
  margin-top: 0.5rem;
}
.upload-controls .control-btn {
  padding: 0.4rem 0.7rem;
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.06);
  color: #eef2ff;
  color: var(--text);
  cursor: pointer;
}

.spotify-search input {
  padding: 0.4rem;
  border-radius: 8px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border: 1px solid var(--border);
  width: 100%;
}
.spotify-search ul li {
  padding: 0.35rem;
}
.spotify-search .logout-btn {
  padding: 0.25rem 0.5rem;
  border-radius: 6px;
}
.platform-toggles {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  color: #9aa4b2;
  color: var(--muted);
}
.check-quality {
  padding: 0.5rem 0.9rem;
  border-radius: 10px;
  background: linear-gradient(90deg, #6d28d9, #8b5cf6);
  background: linear-gradient(90deg, var(--brand), var(--brand-2));
  border: none;
  color: #fff;
  cursor: pointer;
}

.badges-list {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}
.badge {
  display: inline-block;
  background: rgba(139, 92, 246, 0.14);
  color: #d6ccff;
  border: 1px solid rgba(139, 92, 246, 0.22);
  padding: 0.25rem 0.6rem;
  border-radius: 999px;
  font-size: 0.85rem;
}

/* Analytics placeholders */
.analytics-charts {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  grid-gap: 0.75rem;
  gap: 0.75rem;
}
.chart {
  height: 140px;
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.05);
  border: 1px dashed rgba(255, 255, 255, 0.12);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #9aa4b2;
  color: var(--muted);
}
.analytics-filters {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  margin-top: 0.75rem;
  color: #9aa4b2;
  color: var(--muted);
}
.analytics-filters input,
.analytics-filters select {
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border: 1px solid var(--border);
  color: #eef2ff;
  color: var(--text);
  padding: 0.4rem 0.6rem;
  border-radius: 8px;
}

/* Cute schedule cards layout */
.schedules-list {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
  grid-gap: 0.75rem;
  gap: 0.75rem;
}

.schedule-row {
  display: none;
} /* hide old row styles */

/* Mobile adjustments */
@media (max-width: 1023px) {
  .analytics-charts {
    grid-template-columns: 1fr;
  }
  .schedules-list {
    grid-template-columns: 1fr;
  }
