/* Snapchat connect banner */
.connect-banner {
  position: fixed;
  top: 64px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 9999;
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.6rem 0.9rem;
  border-radius: 10px;
  min-width: 320px;
  max-width: 90%;
  box-shadow: 0 6px 18px rgba(11, 18, 32, 0.6);
  border: 1px solid rgba(255, 255, 255, 0.06);
}
.connect-success {
  background: linear-gradient(90deg, rgba(34, 197, 94, 0.12), rgba(16, 185, 129, 0.06));
  color: #dff7ec;
}
.connect-error {
  background: linear-gradient(90deg, rgba(239, 68, 68, 0.08), rgba(220, 38, 38, 0.04));
