/* Authoritative phone/tablet layout. Keep this last so older dashboard rules cannot
   move the menu off-canvas with a second, conflicting positioning method. */
@media (max-width: 1023px) {
  html.dashboard-mode,
  body.dashboard-mode {
    width: 100%;
    max-width: 100%;
    height: auto !important;
    min-height: 100%;
    overflow-x: hidden !important;
    overflow-y: auto !important;
    overscroll-behavior-x: none;
    overscroll-behavior-y: auto;
  }

  .dashboard-root,
  .dashboard-root * {
    box-sizing: border-box;
  }

  .dashboard-root {
    width: 100%;
    max-width: 100%;
    min-width: 0;
    padding-top: 64px;
    padding-bottom: calc(64px + env(safe-area-inset-bottom));
    overflow-x: hidden !important;
    overflow-y: visible;
    overscroll-behavior-y: auto;
    touch-action: pan-y pinch-zoom;
  }

  .dashboard-topbar {
    z-index: 10002;
    padding-left: max(0.65rem, env(safe-area-inset-left));
    padding-right: max(0.65rem, env(safe-area-inset-right));
  }

  .sidebar-backdrop {
    inset: 64px 0 0;
    z-index: 10000;
    border: 0;
  }

  .dashboard-sidebar,
  .dashboard-sidebar.open {
    left: 0 !important;
    right: auto !important;
    top: 64px !important;
    bottom: 0 !important;
    width: min(86vw, 320px);
    height: calc(100dvh - 64px);
    max-height: calc(100dvh - 64px);
    padding: 0.75rem max(0.75rem, env(safe-area-inset-right))
      max(0.75rem, env(safe-area-inset-bottom)) max(0.75rem, env(safe-area-inset-left));
    z-index: 10001;
    overflow: hidden;
    transform: translateX(-105%) !important;
    transition: transform 0.22s ease;
  }

  .dashboard-sidebar.open {
    transform: translateX(0) !important;
  }

  .profile-section,
  .logout-btn {
    flex: 0 0 auto;
  }

  .profile-section {
    padding: 0.8rem;
  }

  .profile-avatar {
    width: 54px;
    height: 54px;
  }

  .dashboard-navbar-vertical {
    display: block;
    flex: 1 1 auto;
    min-height: 0;
    margin-top: 0.75rem;
    overflow-x: hidden;
    overflow-y: auto;
    overscroll-behavior: contain;
    -webkit-overflow-scrolling: touch;
  }

  .dashboard-navbar-vertical ul {
    padding-bottom: 0.5rem;
  }

  .dashboard-navbar-vertical li {
    min-height: 44px;
  }

  .logout-btn {
    position: static;
    min-height: 46px;
    margin: 0.7rem 0 0;
  }

  .dashboard-main,
  .dashboard-main > *,
  .dashboard-main form,
  .dashboard-main fieldset {
    min-width: 0;
    max-width: 100%;
  }

  .dashboard-main {
    width: 100% !important;
    margin: 0 !important;
    padding: 0.75rem max(0.75rem, env(safe-area-inset-right))
      calc(1rem + env(safe-area-inset-bottom)) max(0.75rem, env(safe-area-inset-left)) !important;
    overflow-x: hidden !important;
  }

  .dashboard-main img,
  .dashboard-main video,
  .dashboard-main canvas {
    max-width: 100%;
  }

  .dashboard-main input:not([type="checkbox"]):not([type="radio"]),
  .dashboard-main select,
  .dashboard-main textarea {
    max-width: 100%;
    font-size: 16px;
  }

  .connect-banner {
    left: max(0.75rem, env(safe-area-inset-left));
    right: max(0.75rem, env(safe-area-inset-right));
    min-width: 0;
    max-width: none;
    transform: none;
  }

  .founding-tester-banner {
    min-width: 0;
    padding: 1rem;
  }
}

@media (max-width: 640px) {
  .dashboard-root {
    padding-top: 52px;
  }

  .sidebar-backdrop {
    inset: 52px 0 0;
  }

  .dashboard-sidebar,
  .dashboard-sidebar.open {
    top: 52px !important;
    height: calc(100dvh - 52px);
    max-height: calc(100dvh - 52px);
  }
}

/* UnifiedPublisher.css */

.unified-publisher-container {
  display: flex;
  flex-direction: column;
  height: auto; /* allow natural document flow */
  min-height: 0; /* avoid forcing viewport-limited height that causes blank scroll gaps */
  background: transparent;
  color: #e2e8f0;
  font-family: "Inter", sans-serif;
  width: 100%;
  overflow: visible; /* allow children to render fully without being clipped */
}

.publisher-header {
  margin-bottom: 2rem;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
  padding-bottom: 1rem;
}

.publisher-header h1 {
  font-size: 1.8rem;
  margin: 0 0 0.5rem 0;
  background: linear-gradient(90deg, #60a5fa, #a78bfa);
  background-clip: text;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.publisher-header p {
  color: #94a3b8;
  margin: 0;
}

.publisher-current-asset {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) minmax(180px, auto) auto;
  align-items: center;
  grid-gap: 12px;
  gap: 12px;
  margin-bottom: 1rem;
  padding: 12px 14px;
  border: 1px solid rgba(148, 163, 184, 0.14);
  border-radius: 13px;
  background: rgba(4, 11, 22, 0.58);
}

.publisher-asset-icon {
  display: grid;
  width: 40px;
  height: 40px;
  place-items: center;
  border: 1px solid rgba(139, 92, 246, 0.32);
  border-radius: 11px;
  color: #c4b5fd;
  background: rgba(109, 74, 255, 0.12);
}

.publisher-asset-icon.has-preview {
  width: 76px;
  overflow: hidden;
  padding: 0;
}

.publisher-asset-icon.has-preview img,
.publisher-asset-icon.has-preview video {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.publisher-current-asset > div:nth-child(2) {
  display: grid;
  min-width: 0;
  grid-gap: 2px;
  gap: 2px;
}

.publisher-current-asset small {
  color: #8290a7;
  font-size: 0.65rem;
  text-transform: uppercase;
}

.publisher-current-asset strong {
  overflow: hidden;
  color: #f8fafc;
  font-size: 0.8rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.publisher-current-asset > div:nth-child(2) > span {
  color: #8290a7;
  font-size: 0.67rem;
}

.publisher-destination-pills {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 5px;
}

.publisher-destination-pills span {
  padding: 5px 7px;
  border: 1px solid rgba(34, 211, 238, 0.2);
  border-radius: 999px;
  color: #a5f3fc;
  background: rgba(34, 211, 238, 0.07);
  font-size: 0.62rem;
}

.publisher-destination-pills em {
  color: #64748b;
  font-size: 0.68rem;
  font-style: normal;
}

.publisher-asset-status {
  padding: 6px 8px;
  border-radius: 999px;
  color: #86efac;
  background: rgba(34, 197, 94, 0.1);
  font-size: 0.65rem;
  font-weight: 700;
}

.feedback-bar {
  margin-top: 1rem;
  padding: 0.75rem;
  background: rgba(59, 130, 246, 0.1);
  border: 1px solid rgba(59, 130, 246, 0.2);
  border-radius: 6px;
  color: #93c5fd;
  font-size: 0.9rem;
}

/* --- Layout --- */
.publisher-layout {
  display: grid;
  grid-template-columns: minmax(320px, 420px) minmax(0, 1fr);
  grid-gap: 2rem;
  gap: 2rem;
  width: 100%;
  align-items: start;
}

.publisher-layout.publisher-step-0,
.publisher-layout.publisher-step-1 {
  display: block;
}

.publisher-step-0 .global-controls,
.publisher-step-1 .global-controls {
  position: static;
  width: min(100%, 760px);
  margin: 0 auto;
}

.publisher-step-1 .platform-toggles {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  grid-gap: 10px;
  gap: 10px;
}

.publisher-step-1 .toggle-btn {
  min-height: 54px;
  padding: 12px 14px;
  border-color: rgba(148, 163, 184, 0.12);
  background: rgba(3, 10, 22, 0.54);
}

.publisher-step-1 .toggle-btn.active {
  border-color: rgba(139, 92, 246, 0.5);
  background: rgba(109, 74, 255, 0.13);
}

.publisher-step-0 .platform-selector,
.publisher-step-0 .platform-workspace,
.publisher-step-0 .scheduling-tools,
.publisher-step-0 .marketing-tools,
.publisher-step-0 .trim-controls,
.publisher-step-0 .transform-controls,
.publisher-step-0 .filter-controls,
.publisher-step-1 .global-card,
.publisher-step-1 .platform-workspace,
.publisher-step-2 .global-controls,
.publisher-step-3 .global-controls {
  display: none;
}

.publisher-step-2,
.publisher-step-3 {
  display: block;
}

.publisher-step-2 .platform-workspace,
.publisher-step-3 .platform-workspace {
  gap: 0;
  padding-bottom: 0 !important;
}

.publisher-step-3 .publisher-platform-heading,
.publisher-step-3 .platform-stack,
.publisher-step-3 .empty-state {
  display: none;
}

.publisher-upload-dropzone {
  display: grid !important;
  min-height: 170px;
  place-items: center;
  align-content: center;
  grid-gap: 7px;
  gap: 7px;
  padding: 24px;
  border: 1px dashed rgba(139, 92, 246, 0.56);
  border-radius: 14px;
  color: #f8fafc !important;
  background:
    radial-gradient(circle at 50% 0%, rgba(109, 74, 255, 0.16), transparent 58%),
    rgba(3, 10, 22, 0.62);
  text-align: center;
  cursor: pointer;
  transition:
    border-color 160ms ease,
    background 160ms ease,
    transform 160ms ease;
}

.publisher-upload-dropzone:hover {
