/* --- Responsive Mobile Tweaks --- */
@media (max-width: 1024px) {
  .publisher-layout {
    grid-template-columns: 1fr; /* Stack sidebar and main content */
    display: flex;
    flex-direction: column;
  }

  .global-controls {
    order: 1; /* Move global controls to top on mobile */
  }

  .platform-workspace {
    order: 2;
  }

  .publisher-header h1 {
    font-size: 1.5rem; /* Smaller title */
  }

  .unified-publisher-container {
    padding: 0; /* Let the upload panel own the viewport gutters */
    overflow-x: hidden; /* Prevent horizontal scroll */
  }

  .upgrade-modal-shell {
    grid-template-columns: 1fr;
    padding: 18px;
  }

  /* Ensure inputs don't overflow */
  .form-group input,
  .form-group textarea,
  .form-group select {
    max-width: 100%;
    box-sizing: border-box; /* Critical for padding calculation */
  }
}

@media (max-width: 700px) {
  .publisher-current-asset {
    grid-template-columns: auto minmax(0, 1fr);
  }

  .publisher-destination-pills,
  .publisher-asset-status {
    grid-column: 1 / -1;
    justify-content: flex-start;
    justify-self: start;
  }

  .publisher-platform-heading {
    align-items: flex-start;
    flex-direction: column;
  }

  .publisher-platform-tabs {
    justify-content: flex-start;
  }
}

@media (max-width: 768px) {
  .upgrade-modal {
    width: min(100vw - 16px, 720px) !important;
    margin: 8px auto;
    border-radius: 22px;
  }

  .upgrade-modal-shell {
    gap: 16px;
    padding: 16px;
  }

  .upgrade-modal-copy {
    padding: 18px;
    border-radius: 18px;
  }

  .upgrade-modal-copy h2 {
    font-size: 1.45rem;
    line-height: 1.15;
  }

  .upgrade-modal-copy p {
    font-size: 0.95rem;
    line-height: 1.5;
  }
}

@media (max-width: 560px) {
  .upgrade-modal {
    width: min(100vw - 10px, 720px) !important;
    border-radius: 18px;
  }

  .upgrade-modal-shell {
    gap: 14px;
    padding: 12px;
  }

  .upgrade-modal-copy {
    padding: 16px;
  }

  .upgrade-modal-copy h2 {
    font-size: 1.28rem;
    margin: 8px 0 10px;
  }

  .upgrade-modal-kicker {
    font-size: 0.72rem;
    padding: 5px 9px;
  }
}

/* Keep desktop readable on smaller laptops by stacking preview under the form. */
@media (max-width: 720px) {
  .platform-card-body {
    grid-template-columns: 1fr;
  }

  .platform-preview-column {
    max-width: 640px;
    width: 100%;
  }
}

@media (max-width: 700px) {
  .publisher-review-grid {
    grid-template-columns: 1fr;
  }

  .publisher-wizard-actions {
    align-items: stretch;
    flex-direction: column-reverse;
  }

  .publisher-wizard-actions > div,
  .publisher-wizard-actions > button {
    width: 100%;
  }

  .publisher-wizard-actions > div .btn-secondary-sm {
    flex: 0 0 auto;
  }

  .publisher-wizard-actions .feedback-message {
    white-space: normal;
  }

  .publisher-step-1 .platform-toggles {
    grid-template-columns: 1fr;
  }
}

