/* CinematicEffectsPanel.css
   Modern glass-dark design system.
   No external deps — pure CSS. */

/* ─── Panel Shell ─────────────────────────────────────────────── */
.cep-panel {
  display: flex;
  flex-direction: column;
  width: 280px;
  height: 100%;
  background: rgba(10, 10, 18, 0.96);
  -webkit-backdrop-filter: blur(18px);
          backdrop-filter: blur(18px);
  border-left: 1px solid rgba(255, 255, 255, 0.07);
  overflow: hidden;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  color: #e2e8f0;
  flex-shrink: 0;
}

/* Slide-in animation when panel opens */
@keyframes cep-slide-in {
  from {
    transform: translateX(100%);
    opacity: 0;
  }
  to {
    transform: translateX(0);
    opacity: 1;
  }
}
.cep-panel {
  animation: cep-slide-in 0.22s cubic-bezier(0.22, 1, 0.36, 1) both;
}

/* ─── Header ─────────────────────────────────────────────────── */
.cep-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 16px 12px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  flex-shrink: 0;
}

.cep-header-left {
  display: flex;
  align-items: center;
  gap: 8px;
}

.cep-header-icon {
  font-size: 18px;
}

.cep-header-title {
  font-size: 14px;
  font-weight: 700;
  letter-spacing: 0.3px;
  background: linear-gradient(135deg, #c084fc, #67e8f9);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
}

.cep-reset-btn {
  padding: 4px 10px;
  font-size: 11px;
  font-weight: 600;
  border-radius: 6px;
  border: 1px solid rgba(255, 100, 100, 0.35);
  background: rgba(255, 80, 80, 0.08);
  color: #f87171;
  cursor: pointer;
  transition: all 0.15s ease;
}
.cep-reset-btn:hover {
  background: rgba(255, 80, 80, 0.18);
  border-color: rgba(255, 100, 100, 0.6);
}

/* ─── Scrollable body ─────────────────────────────────────────── */
.cep-body {
  flex: 1 1;
  overflow-y: auto;
  overflow-x: hidden;
  padding: 6px 0 24px;
  scrollbar-width: thin;
  scrollbar-color: rgba(255, 255, 255, 0.12) transparent;
}
.cep-body::-webkit-scrollbar {
  width: 4px;
}
.cep-body::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.12);
  border-radius: 99px;
}

/* ─── Section ─────────────────────────────────────────────────── */
.cep-section {
  padding: 14px 16px 6px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.04);
}

.cep-section-heading {
  display: flex;
  align-items: center;
  gap: 7px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.35);
  margin-bottom: 12px;
}

.cep-section-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: linear-gradient(135deg, #c084fc, #67e8f9);
  flex-shrink: 0;
}

/* ─── Preset Cards ────────────────────────────────────────────── */
.cep-presets-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  grid-gap: 8px;
  gap: 8px;
  margin-bottom: 4px;
}
/* Last preset (5th) centers alone on bottom row */
.cep-presets-grid .cep-preset-card:last-child:nth-child(odd) {
  grid-column: span 2;
}

.cep-preset-card {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 5px;
  padding: 12px 8px 10px;
  border-radius: 12px;
  border: 1px solid rgba(255, 255, 255, 0.07);
  background: rgba(255, 255, 255, 0.03);
  cursor: pointer;
  transition: all 0.18s ease;
  text-align: center;
  color: #e2e8f0;
}
.cep-preset-card:hover {
  background: rgba(255, 255, 255, 0.07);
  border-color: rgba(255, 255, 255, 0.15);
  transform: translateY(-1px);
}
.cep-preset-card.is-active {
