  color: #c084fc;
  font-feature-settings: "tnum";
}

/* Custom range styling */
.cep-range {
  appearance: none;
  width: 100%;
  height: 4px;
  border-radius: 99px;
  background: rgba(255, 255, 255, 0.1);
  outline: none;
  cursor: pointer;
  transition: background 0.15s;
}
.cep-range::-webkit-slider-thumb {
  appearance: none;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: linear-gradient(135deg, #c084fc, #818cf8);
  box-shadow: 0 0 8px rgba(192, 132, 252, 0.5);
  cursor: pointer;
  border: 2px solid rgba(255, 255, 255, 0.2);
  -webkit-transition:
    transform 0.15s,
    box-shadow 0.15s;
  transition:
    transform 0.15s,
    box-shadow 0.15s;
}
.cep-range::-webkit-slider-thumb:hover {
  transform: scale(1.2);
  box-shadow: 0 0 14px rgba(192, 132, 252, 0.7);
}
.cep-range::-moz-range-thumb {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: linear-gradient(135deg, #c084fc, #818cf8);
  cursor: pointer;
  border: 2px solid rgba(255, 255, 255, 0.2);
}
.cep-range:focus-visible {
  outline: 2px solid rgba(192, 132, 252, 0.6);
  outline-offset: 3px;
  border-radius: 99px;
}

