  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  overflow: hidden;
}

/* In VideoEditor the wrapper fills available space */
.video-preview .cep-media-wrapper {
  height: 100%;
}

/* In MultiCam the wrapper sizes to the preview stage inside */
.nle-preview-panel .cep-media-wrapper {
  height: auto;
  display: block;
  width: 100%;
  border-radius: 16px;
}

/* ─── Responsive for small screens ───────────────────────────── */
@media (max-width: 600px) {
