    width: 100%;
    height: auto;
    max-height: 55vh;
    border-left: none;
    border-top: 1px solid rgba(255, 255, 255, 0.07);
    animation: none;
  }
}

/* ─── Film Grain animation ───────────────────────────────────── */
@keyframes cep-grain-drift {
  0% {
    transform: translate(0, 0);
  }
  25% {
    transform: translate(-2px, 3px);
  }
  50% {
    transform: translate(3px, -1px);
  }
  75% {
    transform: translate(-1px, -3px);
  }
  100% {
    transform: translate(0, 0);
  }
}

