  transform-origin: 50% 38%;
}
.creator-canvas-snap {
  animation: creatorSnap 0.55s steps(2, end) both;
  transform-origin: 50% 38%;
}
.creator-canvas-crash {
  animation: creatorCrash 0.48s cubic-bezier(0.85, 0.02, 0.2, 1) both;
  transform-origin: 50% 38%;
}
.creator-canvas-shake {
  animation: creatorShake 0.46s linear infinite;
}
.creator-canvas-stabilized {
  transform: scale(1.035);
  transition: transform 0.4s ease;
}
.creator-canvas-parallax {
  animation: creatorCanvasParallax 4.8s ease-in-out infinite alternate;
  transform-origin: 42% 48%;
}

@keyframes creatorPunch {
  0% {
    transform: scale(1);
  }
  42% {
    transform: scale(1.34);
  }
  100% {
    transform: scale(1.09);
  }
}
@keyframes creatorSnap {
  0% {
    transform: scale(1);
  }
  35%,
  100% {
    transform: scale(1.42);
  }
}
@keyframes creatorCrash {
  0% {
    transform: scale(1);
    filter: blur(0);
  }
  65% {
    transform: scale(1.62);
    filter: blur(1.6px);
  }
  100% {
    transform: scale(1.18);
    filter: blur(0);
  }
}
@keyframes creatorShake {
  0%,
  100% {
    transform: translate(0);
  }
  20% {
    transform: translate(-1.3%, 0.8%) rotate(-0.35deg);
  }
  40% {
    transform: translate(1.1%, -0.7%) rotate(0.3deg);
  }
  60% {
    transform: translate(-0.6%, -0.35%);
  }
  80% {
    transform: translate(0.55%, 0.35%);
  }
}
@keyframes creatorCanvasParallax {
  from {
    transform: scale(1.025) translateX(-0.5%);
  }
  to {
    transform: scale(1.075) translateX(1.6%);
  }
}

