.overlays-layer {
  position: absolute;
  inset: 0;
  /* A positioned stacking group would give mixed children a transparent
     backdrop, so their blend modes could not see the source canvas. Keep the
     existing per-layer z order on the shared programme stacking context. */
  z-index: auto;
  pointer-events: none;
}

.overlays-layer > .hook-preview-shade,
.overlays-layer > .hook-preview-accent,
.overlays-layer > .hook-preview-bars,
