.studio-motion-path {
  position: absolute;
  inset: 0;
  z-index: 520;
  width: 100%;
  height: 100%;
  overflow: visible;
  pointer-events: none;
  filter: drop-shadow(0 0 4px rgba(75, 226, 238, 0.48));
}

.studio-motion-path polyline {
  fill: none;
  stroke: rgba(104, 237, 246, 0.96);
  stroke-width: 1.5px;
  stroke-dasharray: 6 5;
  vector-effect: non-scaling-stroke;
}

.studio-motion-path-key {
  fill: #091323;
  stroke: #a98aff;
  stroke-width: 1.5px;
  cursor: pointer;
  pointer-events: auto;
  touch-action: none;
}
.studio-motion-path-key[aria-disabled="true"] { cursor: default; opacity: .55; }
.studio-motion-path-coordinate { font-size: 2px; fill: #fff; stroke: #091323; stroke-width: .12px; paint-order: stroke; }

.studio-motion-path-key:hover,
.studio-motion-path-key:focus {
  fill: #a98aff;
  outline: none;
}

.studio-motion-path-current {
  fill: rgba(76, 225, 236, 0.28);
  stroke: #62eef6;
  stroke-width: 2px;
  pointer-events: none;
}

.studio-path-tangent { stroke: #ffcd75; stroke-width: 1px; vector-effect: non-scaling-stroke; }
.studio-path-handle { fill: #ffcd75; stroke: #20150a; stroke-width: 1px; vector-effect: non-scaling-stroke;
  cursor: grab; pointer-events: auto; touch-action: none; }
.studio-path-handle:focus { stroke: #fff; outline: none; }
.studio-path-handle[aria-disabled="true"] { opacity: .5; cursor: default; }
.studio-motion-path-toolbar { position: absolute; bottom: 8px; right: 8px; z-index: 521; display: flex;
  align-items: center; gap: 8px; flex-wrap: wrap; max-width: calc(100% - 16px); padding: 6px 9px;
  border: 1px solid #8e7649; border-radius: 7px; background: #111020eb; color: #f7e6c7; font-size: 12px; }
.studio-motion-path-toolbar button { padding: 5px 8px; border: 1px solid #bf9954; border-radius: 5px;
  background: #352818; color: #ffe2a6; cursor: pointer; }
.studio-motion-path-toolbar button:disabled { opacity: .5; cursor: default; }
.studio-motion-path-toolbar small { display: none; }

