/* ── B-Roll animation keyframes ── */

@keyframes brollFadeIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
    opacity: var(--layer-opacity, 1);
  }
}

@keyframes brollFadeOut {
  from {
    opacity: 1;
    opacity: var(--layer-opacity, 1);
  }
  to {
    opacity: 0;
  }
}

@keyframes brollSlideLeftIn {
  from {
    transform: translateX(100%);
    opacity: 0;
  }
  to {
    transform: translateX(0);
    opacity: 1;
  }
}

@keyframes brollSlideLeftOut {
  from {
    transform: translateX(0);
    opacity: 1;
  }
  to {
    transform: translateX(-100%);
    opacity: 0;
  }
}

@keyframes brollSlideRightIn {
  from {
    transform: translateX(-100%);
    opacity: 0;
  }
  to {
    transform: translateX(0);
    opacity: 1;
  }
}

@keyframes brollSlideRightOut {
  from {
    transform: translateX(0);
    opacity: 1;
  }
  to {
    transform: translateX(100%);
    opacity: 0;
  }
}

@keyframes brollSlideUpIn {
  from {
    transform: translateY(100%);
    opacity: 0;
  }
  to {
    transform: translateY(0);
    opacity: 1;
  }
}

@keyframes brollSlideUpOut {
  from {
    transform: translateY(0);
    opacity: 1;
  }
  to {
    transform: translateY(-100%);
    opacity: 0;
  }
}

@keyframes brollSlideDownIn {
  from {
    transform: translateY(-100%);
    opacity: 0;
  }
  to {
    transform: translateY(0);
    opacity: 1;
  }
}

@keyframes brollSlideDownOut {
  from {
    transform: translateY(0);
    opacity: 1;
  }
  to {
    transform: translateY(100%);
    opacity: 0;
  }
}

@keyframes brollZoomIn {
  from {
    transform: scale(0.3);
    opacity: 0;
  }
  to {
    transform: scale(1);
    opacity: 1;
  }
}

@keyframes brollZoomOut {
  from {
    transform: scale(1);
    opacity: 1;
  }
  to {
    transform: scale(0.3);
    opacity: 0;
  }
}

/* Enter animations — triggered when overlay appears */
.draggable-overlay.broll-anim-fade {
  animation: brollFadeIn 0.3s ease forwards;
}

.draggable-overlay.broll-anim-slideLeft {
  animation: brollSlideLeftIn 0.35s ease forwards;
}

.draggable-overlay.broll-anim-slideRight {
  animation: brollSlideRightIn 0.35s ease forwards;
}

.draggable-overlay.broll-anim-slideUp {
  animation: brollSlideUpIn 0.35s ease forwards;
}

.draggable-overlay.broll-anim-slideDown {
  animation: brollSlideDownIn 0.35s ease forwards;
}

.draggable-overlay.broll-anim-zoom {
  animation: brollZoomIn 0.35s ease forwards;
}

