@media (max-width: 1280px) {
  .hook-broll-only-mode .studio-layout {
    grid-template-columns: minmax(200px, 0.38fr) minmax(390px, 1fr) minmax(330px, 0.7fr);
  }

  .studio-project-rail {
    padding-right: 9px;
    padding-left: 9px;
  }
}

@media (max-width: 1050px) {
  .hook-broll-only-mode .studio-layout {
    grid-template-columns: minmax(0, 1fr) minmax(340px, 0.72fr);
    grid-template-rows: auto minmax(0, 1fr);
  }

  .studio-project-rail {
    grid-column: 1 / -1;
    display: grid;
    grid-template-columns: minmax(180px, 0.45fr) minmax(260px, 0.75fr) minmax(260px, 0.8fr);
    max-height: 210px;
    overflow-y: auto;
    border-right: 0;
    border-bottom: 1px solid var(--studio-border);
  }

