  .studio-project-rail__footer {
    display: none;
  }

  .studio-project-rail .studio-workflow-nav {
    align-self: start;
  }

  .studio-project-rail .studio-workflow-nav ol {
    grid-template-columns: repeat(2, minmax(0, 1fr));
