  .studio-project-rail .studio-workflow-nav__intro,
  .studio-project-rail .studio-workflow-nav__status {
    display: none;
  }
}

@media (max-width: 760px) {
  .hook-broll-only-mode .studio-layout {
    display: block;
    overflow-y: auto;
  }

  .studio-project-rail {
    display: grid;
    max-height: none;
    grid-template-columns: 1fr;
  }

  .studio-project-rail .studio-workflow-nav ol {
    grid-template-columns: repeat(4, minmax(126px, 1fr));
    overflow-x: auto;
  }

  .studio-project-rail .studio-workflow-nav li small {
    max-width: none;
  }

  .studio-project-list__items--moments {
    max-height: 180px;
  }
}

/* Focused Viral Clip Studio: synchronized comparison + one-task inspector. */
.hook-broll-only-mode
  .studio-sidebar
  > .studio-panel:not(.clip-inspector-panel):not(.export-panel) {
  display: none;
}

.hook-broll-only-mode .phone-preview-container > .studio-panel:not(.preview-panel) {
