.studio-finish-layer-stack {
  position: absolute;
  inset: 0;
  z-index: 19;
  overflow: hidden;
  border-radius: inherit;
  pointer-events: none;
}

.studio-audio-visualizer {
  position: absolute;
  inset: 0;
  z-index: 8;
  width: 100%;
  height: 100%;
  opacity: 0.78;
  filter: saturate(1.05);
}

.studio-chromatic-layer,
.studio-vhs-layer,
.studio-light-leak-layer {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.studio-chromatic-layer {
  z-index: 4;
  opacity: calc(var(--chromatic-strength) * 0.7);
  background:
    linear-gradient(90deg, rgba(255, 15, 90, 0.24), transparent 5% 95%, rgba(35, 222, 255, 0.25)),
    repeating-linear-gradient(0deg, transparent 0 5px, rgba(106, 230, 255, 0.035) 6px);
  mix-blend-mode: screen;
  animation: studio-rgb-edge 2.8s steps(2, end) infinite;
}

.studio-vhs-layer {
  z-index: 5;
  opacity: calc(var(--vhs-strength) * 0.58);
  background: repeating-linear-gradient(
    0deg,
    rgba(255, 255, 255, 0.05) 0,
    rgba(255, 255, 255, 0.05) 1px,
    transparent 2px,
    transparent 5px
  );
  mix-blend-mode: soft-light;
  animation: studio-vhs-track 1.7s linear infinite;
}

.studio-light-leak-layer {
  z-index: 6;
  opacity: calc(var(--light-leak-strength) * 0.72);
  background:
    radial-gradient(circle at 8% 20%, rgba(255, 72, 40, 0.72), transparent 31%),
    radial-gradient(circle at 95% 76%, rgba(255, 184, 65, 0.48), transparent 34%);
  mix-blend-mode: screen;
  animation: studio-light-leak 5.5s ease-in-out infinite alternate;
}

@keyframes studio-rgb-edge {
  0%,
  88%,
  100% {
    transform: translateX(0);
  }
  90% {
    transform: translateX(2px);
  }
  94% {
    transform: translateX(-2px);
  }
}

@keyframes studio-vhs-track {
  from {
    background-position: 0 0;
  }
  to {
    background-position: 0 24px;
  }
}

@keyframes studio-light-leak {
  from {
    transform: translate3d(-4%, -2%, 0) scale(1.05);
  }
  to {
    transform: translate3d(5%, 3%, 0) scale(1.16);
  }
}

