  }
  to {
    transform: scale(1.12) translateX(-4%);
  }
}
@keyframes ken-burns-pan-right {
  from {
    transform: scale(1.12) translateX(-4%);
  }
  to {
    transform: scale(1.12) translateX(4%);
  }
}
@keyframes ken-burns-pan-up {
  from {
    transform: scale(1.12) translateY(3%);
  }
  to {
    transform: scale(1.12) translateY(-3%);
  }
}

