/* ── Extra B-roll entrance animations ── */
@keyframes broll-slide-left {
  from {
    transform: translateX(100%);
    opacity: 0;
  }
  to {
    transform: translateX(0);
    opacity: 1;
  }
}
@keyframes broll-pop {
  0% {
    transform: scale(0);
    opacity: 0;
  }
  60% {
    transform: scale(1.15);
    opacity: 1;
  }
  100% {
    transform: scale(1);
    opacity: 1;
  }
}
@keyframes broll-wipe {
  from {
    clip-path: inset(0 100% 0 0);
  }
  to {
    clip-path: inset(0 0 0 0);
  }
}
@keyframes broll-blur-in {
  from {
    filter: blur(20px);
    opacity: 0;
  }
  to {
    filter: blur(0);
    opacity: 1;
  }
}

.broll-anim-slideLeft {
  animation: broll-slide-left 0.3s ease-out both;
}
.broll-anim-pop {
  animation: broll-pop 0.35s cubic-bezier(0.34, 1.56, 0.64, 1) both;
}
.broll-anim-wipe {
  animation: broll-wipe 0.4s ease-out both;
}
.broll-anim-blur {
