  font-size: .71rem;
}
.schedule-release-date > span { color: #97aad0; font-size: 1rem; margin-right: 2px; }
.schedule-release-kind { display: grid; grid-gap: 1px; gap: 1px; min-width: 0; }
.schedule-release-kind strong { font-size: .78rem; white-space: nowrap; }
.schedule-release-kind .schedule-variant { font-size: .52rem; letter-spacing: .06em; }
.schedule-release-arrow { font-size: 1.4rem; color: #c1cde0; line-height: .7; }
.schedule-release-list > .schedule-history-toggle {
