  gap: 12px;
  margin-bottom: 10px;
}
.schedule-media {
  width: 100%;
  max-height: none;
  height: 315px;
  aspect-ratio: auto;
  border-radius: 8px;
}
.schedule-overview { display: flex; flex-direction: column; }
.schedule-copy { min-height: 68px; }
.schedule-copy strong { font-size: .88rem; }
.schedule-copy p { margin: 4px 0 7px; font-size: .78rem; line-height: 1.35; -webkit-line-clamp: 2; }
.schedule-timing {
  display: grid;
  grid-template-columns: 1fr minmax(145px, 1.15fr);
  grid-column-gap: 10px;
  column-gap: 10px;
  border: 0;
  margin: 0 0 9px;
}
.schedule-timing div {
  grid-template-columns: 75px minmax(0, 1fr);
  gap: 3px;
  padding: 3px 0;
  border: 0;
  font-size: .7rem;
}
.schedule-timing div:last-child { grid-column: 1/-1; }
.schedule-timing small { font-size: .62rem; }
.schedule-destinations h4 { margin: 0 0 5px; font-size: .83rem; }
.schedule-destination { margin-bottom: 0; border-radius: 0; border-bottom: 0; }
.schedule-destination:first-of-type { border-radius: 8px 8px 0 0; }
.schedule-destination:last-child { border-bottom: 1px solid #273a52; border-radius: 0 0 8px 8px; }
.schedule-destination-toggle {
  grid-template-columns: 23px minmax(80px, 1fr) auto 13px;
  gap: 7px;
  min-height: 31px;
  padding: 4px 8px;
}
.schedule-destination-toggle strong { font-size: .75rem; }
.schedule-destination-toggle .schedule-status { font-size: .68rem; }
.schedule-platform-icon { width: 20px; height: 20px; }
.platform-instagram { background: linear-gradient(35deg, #f9b23f, #e02f79 55%, #7354e8); font-size: 1.05rem; }
.platform-linkedin { font-size: .57rem; border-radius: 4px; }
.platform-reddit { font-size: .6rem; }
.platform-tiktok { font-size: 1rem; color: #ff557b; text-shadow: -1px -1px #59eced; }
.platform-youtube { border-radius: 5px; font-size: .58rem; }
.schedule-release-actions { flex-wrap: nowrap; margin-top: 8px; gap: 6px; }
.schedule-release-actions button { min-height: 35px; padding: 6px 8px; font-size: .68rem; white-space: nowrap; }
.schedule-release-actions button::before { display: inline-block; margin-right: 5px; color: #dce8ff; }
.schedule-release-actions button:nth-child(1)::before { content: '◉'; }
.schedule-release-actions button:nth-child(2)::before { content: '✎'; }
.schedule-release-actions button:nth-child(3)::before { content: '▣'; }
.schedule-release-actions button:nth-child(4)::before { content: 'Ⅱ'; }
.schedule-release-actions button:nth-child(5)::before { content: '⊗'; color: #ff929c; }
.schedule-release-actions small { white-space: normal; font-size: .58rem; }
.schedule-copy-limit { font-size: .65rem; margin-top: 6px; }
.schedule-calendar { margin-top: 12px; padding: 12px 14px; }
.schedule-calendar header { align-items: center; margin-bottom: 9px; }
.schedule-calendar header h3 { font-size: 1.04rem; }
.schedule-calendar header p { font-size: .67rem; }
.schedule-legend .schedule-status { font-size: .65rem; }
.schedule-legend .schedule-status::before {
  content: '';
  display: inline-block;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  margin-right: 4px;
  background: currentColor;
}
.schedule-calendar-grid { grid-template-columns: repeat(6, minmax(0, 1fr)); gap: 6px; }
.schedule-calendar-card { gap: 4px; min-height: 115px; padding: 8px; border-radius: 8px; }
.schedule-calendar-date { width: 100%; display: flex; justify-content: space-between; align-items: center; gap: 2px; }
.schedule-calendar-date small { white-space: nowrap; font-size: .61rem; }
.schedule-calendar-date .schedule-status { border: 1px solid #197d5b; background: #0a332e; padding: 2px 5px; font-size: .56rem; }
.schedule-calendar-card > .schedule-variant { font-size: .52rem; }
.schedule-calendar-card strong { font-size: .72rem; line-height: 1.2; }
.schedule-calendar-card em { color: #aabbd1; font-size: .61rem; }
.schedule-calendar-platforms { gap: 2px; margin-top: auto; }
.schedule-calendar-platforms .schedule-platform-icon { width: 17px; height: 17px; font-size: .56rem; }

@media (max-width: 1320px) {
  .schedule-workspace { grid-template-columns: minmax(260px, 31%) minmax(0, 1fr); }
  .schedule-kpis article { grid-template-columns: 42px 1fr; column-gap: 8px; padding: 8px; }
  .schedule-kpi-icon { width: 40px; height: 44px; font-size: 1.4rem !important; }
  .schedule-kpi-icon.paused { width: 34px; height: 34px; margin: 5px; }
  .schedule-detail-main { grid-template-columns: minmax(135px, 28%) minmax(0, 1fr); }
  .schedule-timing { display: block; }
  .schedule-timing div { grid-template-columns: 72px minmax(0, 1fr); }
  .schedule-release-actions { flex-wrap: wrap; }
  .schedule-release-actions button { flex: 1 1 30%; }
  .schedule-calendar-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
}
@media (max-width: 800px) {
  .schedule-workspace { grid-template-columns: 1fr; }
  .schedule-release-list { display: block; }
  .schedule-subject { display: inline-block; width: min(100%, 320px); vertical-align: top; margin-right: 6px; }
  .schedule-detail-main { grid-template-columns: minmax(140px, 28%) minmax(0, 1fr); }
  .schedule-calendar-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 540px) {
  .schedule-kpis { gap: 7px; }
  .schedule-kpis article { min-height: 63px; }
  .schedule-kpis strong { font-size: 1.2rem; }
  .schedule-kpis article > span:not(.schedule-kpi-icon) { font-size: .67rem; }
  .schedule-detail-main { grid-template-columns: 1fr; }
  .schedule-media { width: min(100%, 230px); height: 270px; }
  .schedule-detail-header h3 { display: block; }
  .schedule-timing { display: grid; }
  .schedule-calendar-grid { grid-template-columns: 1fr 1fr; }
  .schedule-calendar-card { min-height: 120px; }
  .schedule-calendar-date { display: block; }
  .schedule-calendar-date .schedule-status { display: table; margin-top: 2px; }
  .schedule-release-actions button { flex: 1 1 44%; }
}

