.security-quick-icon {
  display: grid;
  width: 40px;
  height: 40px;
  place-items: center;
  border: 1px solid rgba(139, 92, 246, 0.3);
  border-radius: 11px;
  color: #c4b5fd;
  background: rgba(109, 74, 255, 0.12);
