  flex-direction: column;
  gap: 20px;
}

.privacy-option {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 16px;
  background: #f8f9fa;
  border-radius: 8px;
}

.privacy-option-info strong {
  display: block;
  margin-bottom: 4px;
  color: #333;
  font-size: 16px;
}

.privacy-option-info p {
  margin: 0;
  color: #666;
  font-size: 14px;
}

/* Toggle Switch */
.toggle-switch {
  position: relative;
  display: inline-block;
  width: 50px;
  height: 26px;
  flex-shrink: 0;
}

.toggle-switch input {
  opacity: 0;
  width: 0;
  height: 0;
}

.toggle-slider {
  position: absolute;
  cursor: pointer;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: #ccc;
  transition: 0.3s;
  border-radius: 26px;
}

.toggle-slider:before {
  position: absolute;
  content: "";
  height: 20px;
  width: 20px;
  left: 3px;
  bottom: 3px;
  background-color: white;
  transition: 0.3s;
  border-radius: 50%;
}

.toggle-switch input:checked + .toggle-slider {
  background-color: #28a745;
}

.toggle-switch input:checked + .toggle-slider:before {
  transform: translateX(24px);
}

/* Security Score */
.security-score {
  display: flex;
  gap: 30px;
  align-items: center;
  flex-wrap: wrap;
}

.score-circle {
  width: 120px;
  height: 120px;
  border-radius: 50%;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 4px 12px rgba(102, 126, 234, 0.3);
}

.score-value {
  font-size: 32px;
  font-weight: 700;
  color: white;
}

.score-recommendations {
  flex: 1 1;
  min-width: 250px;
}

.score-recommendations h4 {
  margin-bottom: 12px;
  color: #555;
  font-size: 16px;
}

.score-recommendations ul {
  list-style: none;
  padding: 0;
  margin: 0;
}

.score-recommendations li {
  padding: 8px 0;
  font-size: 14px;
}

.score-recommendations li.completed {
  color: #28a745;
}

.score-recommendations li.pending {
  color: #ffc107;
}

/* Two-Factor Authentication */
.twofa-enabled {
  text-align: center;
  padding: 20px;
}

.success-badge {
  display: inline-block;
  background: #28a745;
  color: white;
  padding: 8px 20px;
  border-radius: 20px;
  font-weight: 600;
  margin-bottom: 12px;
}

.twofa-setup .phone-input,
.twofa-setup .code-input {
  width: 100%;
  max-width: 300px;
  padding: 12px;
  font-size: 16px;
  border: 2px solid #ddd;
  border-radius: 8px;
  margin-bottom: 8px;
}

.twofa-setup .input-hint {
  display: block;
  color: #666;
  font-size: 13px;
  margin-top: 4px;
  margin-bottom: 12px;
}

#recaptcha-container {
  margin: 12px 0;
}

/* Connected Platforms */
.connected-platforms-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.platform-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 16px;
  border: 1px solid #e0e0e0;
  border-radius: 8px;
  background: #f9f9f9;
}

.platform-info {
  display: flex;
  align-items: center;
  gap: 12px;
}

.platform-icon {
  font-size: 32px;
  width: 48px;
  height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: white;
  border-radius: 8px;
}

.platform-details {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.platform-details strong {
  font-size: 16px;
  color: #333;
}

.platform-details small {
  font-size: 13px;
  color: #666;
}

.platform-scope {
  font-size: 12px;
  color: #888;
  padding: 2px 8px;
  background: #e8e8e8;
  border-radius: 4px;
  display: inline-block;
  margin-top: 4px;
}

.btn-disconnect {
  padding: 8px 16px;
  background: #dc3545;
  color: white;
  border: none;
  border-radius: 6px;
  cursor: pointer;
  font-weight: 600;
  transition: background 0.2s;
}

.btn-disconnect:hover {
  background: #c82333;
}

.no-platforms {
  text-align: center;
  padding: 30px;
  color: #666;
}

.no-platforms p {
  margin-bottom: 8px;
  font-size: 16px;
}

.no-platforms small {
  font-size: 14px;
  color: #999;
}

.loading-platforms {
  text-align: center;
  padding: 20px;
  color: #666;
}

/* Responsive */
@media (max-width: 768px) {
  .security-panel {
    padding: 16px;
  }

  .security-card {
    padding: 16px;
  }

  .security-quick-grid {
    grid-template-columns: 1fr;
  }

  .security-quick-grid article {
    grid-template-columns: auto minmax(0, 1fr);
  }

  .security-quick-grid article > button,
  .security-quick-status {
    grid-column: 1 / -1;
    justify-self: start;
  }

  .privacy-option {
    flex-direction: column;
    align-items: flex-start;
    gap: 12px;
  }

  .toggle-switch {
    align-self: flex-end;
  }

  .security-score {
    flex-direction: column;
    align-items: flex-start;
  }

  .platform-item {
    flex-direction: column;
    align-items: flex-start;
    gap: 12px;
  }

  .btn-disconnect {
    width: 100%;
  }
}

/* EngagementMarketplace.css - The Billionaire's Wolf Hunt Edition */

body {
  background-color: #050505;
}

.wolf-hunt-dashboard {
  font-family: "Inter", "Segoe UI", sans-serif;
  color: #e0e0e0;
  max-width: 1400px;
  margin: 0 auto;
  padding: 2rem;
  background: radial-gradient(circle at top right, #1a1a2e 0%, #000000 40%);
  min-height: 100vh;
}

/* --- HEADER & STATUS BAR --- */
.hunt-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 3rem;
  border-bottom: 2px solid #222;
  padding-bottom: 1.5rem;
}

.brand-title h1 {
  font-size: 2.5rem;
  font-weight: 900;
  margin: 0;
  background: linear-gradient(90deg, #fff, #888);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  letter-spacing: -1px;
}

.brand-title .tagline {
  font-size: 0.9rem;
  color: #666;
  text-transform: uppercase;
  letter-spacing: 2px;
  display: block;
  margin-top: 5px;
}

.status-bar {
  display: flex;
  gap: 2rem;
}

.stat-card {
  background: #111;
  border: 1px solid #333;
  padding: 0.8rem 1.5rem;
  border-radius: 8px;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  min-width: 120px;
}

.stat-label {
  font-size: 0.7rem;
  color: #888;
  text-transform: uppercase;
  margin-bottom: 4px;
}

.stat-value {
  font-size: 1.5rem;
  font-weight: 700;
  color: #fff;
}

.stat-value.gold {
  color: #ffd700;
  text-shadow: 0 0 10px rgba(255, 215, 0, 0.4);
}

.energy-bar-container {
  width: 100%;
  height: 4px;
  background: #222;
  margin-top: 5px;
  border-radius: 2px;
  overflow: hidden;
}

.energy-fill {
  height: 100%;
  background: #00ff88;
  box-shadow: 0 0 8px #00ff88;
}

/* --- MAIN GRID LAYOUT --- */
.hunt-grid {
  display: grid;
  grid-template-columns: 2fr 1fr;
  grid-gap: 2rem;
  gap: 2rem;
}

@media (max-width: 1024px) {
  .hunt-grid {
    grid-template-columns: 1fr;
  }
}

/* --- FEEDING GROUNDS (Task List) --- */
.feeding-grounds-section,
.war-room-section {
  background: #0a0a0a;
  border: 1px solid #222; /* Default border */
  border-radius: 12px;
  padding: 1.5rem;
}

/* Section Titles with 'HUD' look */
.section-hud-title {
  font-size: 1.2rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: #ffd700;
  margin-bottom: 1.5rem;
  display: flex;
  align-items: center;
  gap: 10px;
}

.section-hud-title::before {
  content: "";
  display: block;
  width: 4px;
  height: 20px;
  background: #ffd700;
}

/* --- TASK CARDS --- */
.bounty-list {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.bounty-card {
  background: linear-gradient(145deg, #111, #0d0d0d);
  border: 1px solid #222;
  border-radius: 8px;
  padding: 1.2rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  transition: all 0.2s ease;
  position: relative;
  overflow: hidden;
}

.bounty-card:hover {
  border-color: #444;
  transform: translateY(-2px);
  box-shadow: 0 5px 20px rgba(0, 0, 0, 0.5);
}

.bounty-card.frenzy {
  border: 1px solid rgba(255, 0, 85, 0.4);
  background: linear-gradient(145deg, #1a0505, #0d0000);
}

.bounty-card.frenzy::after {
  content: "FRENZY";
  position: absolute;
  top: 10px;
  right: -20px;
  background: #ff0055;
  color: white;
  font-size: 0.6rem;
  padding: 2px 25px;
  transform: rotate(45deg);
  font-weight: 800;
}

.bounty-info h3 {
  margin: 0;
  font-size: 1.1rem;
  color: #fff;
  display: flex;
  align-items: center;
  gap: 10px;
}

.platform-tag {
  font-size: 0.7rem;
  padding: 2px 6px;
  border-radius: 4px;
  background: #333;
  color: #aaa;
  text-transform: uppercase;
}

.bounty-meta {
  display: flex;
  gap: 15px;
  margin-top: 8px;
  font-size: 0.85rem;
  color: #777;
}

.meta-item {
  display: flex;
  align-items: center;
  gap: 5px;
}

.meta-item.urgent {
  color: #ff4444;
}

.bounty-action {
  text-align: right;
}

.reward-badge {
  font-size: 1.4rem;
  font-weight: 800;
  color: #ffd700;
  display: block;
  margin-bottom: 5px;
}

.hunt-btn {
  background: #fff;
  color: #000;
  border: none;
  padding: 8px 20px;
  font-weight: 700;
  text-transform: uppercase;
  border-radius: 2px;
  cursor: pointer;
  transition: all 0.2s;
  letter-spacing: 1px;
}

.hunt-btn:hover {
  background: #ffd700;
  box-shadow: 0 0 15px rgba(255, 215, 0, 0.5);
}

.hunt-btn:disabled {
  background: #333;
  color: #555;
  cursor: not-allowed;
  box-shadow: none;
}

/* --- ACTIVE MISSION MODAL / PANEL --- */
.active-mission-panel {
  margin-top: 20px;
  background: #151515;
  border: 1px solid #ffd700;
  padding: 1.5rem;
  border-radius: 8px;
  animation: slideDown 0.3s ease-out;
}

@keyframes slideDown {
  from {
    opacity: 0;
    transform: translateY(-10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.mission-timer {
  font-family: "Courier New", monospace;
  font-size: 2rem;
  color: #ffd700;
  text-align: center;
  margin: 1rem 0;
  text-shadow: 0 0 10px rgba(255, 215, 0, 0.3);
}

.mission-steps {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.step-btn {
  width: 100%;
  padding: 12px;
  background: #222;
  border: 1px solid #444;
  color: #fff;
  text-align: left;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.step-btn.completed {
  border-color: #00ff88;
  color: #00ff88;
}

.step-btn.primary {
  background: #ffd700;
  color: #000;
  font-weight: 800;
  justify-content: center;
  border: none;
  font-size: 1rem;
}

.step-btn.primary:hover {
  filter: brightness(1.1);
}

/* --- WAR ROOM (Create Campaign) --- */
.create-campaign-form {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.form-group label {
  display: block;
  margin-bottom: 8px;
  color: #aaa;
  font-size: 0.9rem;
}

.dark-input,
.dark-select {
  width: 100%;
  background: #111;
  border: 1px solid #333;
  padding: 12px;
  color: #fff;
  border-radius: 4px;
  font-family: inherit;
}

.dark-input:focus,
.dark-select:focus {
  border-color: #ffd700;
  outline: none;
}

.cost-summary {
  background: #111;
  padding: 1rem;
  border-radius: 4px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-left: 3px solid #ffd700;
}

.launch-btn {
  background: linear-gradient(90deg, #ffd700, #ffaa00);
  border: none;
  padding: 15px;
  color: #000;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: 2px;
  cursor: pointer;
  font-size: 1.1rem;
  transition: transform 0.1s;
}

.launch-btn:hover {
  transform: scale(1.02);
}

/* --- NOTIFICATIONS --- */
.notification-toast {
  position: fixed;
  bottom: 20px;
  right: 20px;
  background: #111;
  border-left: 4px solid #00ff88;
  padding: 1rem 2rem;
  color: #fff;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.8);
  z-index: 1000;
  animation: slideIn 0.3s ease-out;
}

.notification-toast.error {
  border-left-color: #ff4444;
}

@keyframes slideIn {
  from {
    transform: translateX(100%);
    opacity: 0;
  }
  to {
    transform: translateX(0);
    opacity: 1;
  }
}

@media (max-width: 720px) {
  .wolf-hunt-dashboard {
    width: 100%;
    max-width: 100%;
    min-width: 0;
    padding: 1rem;
    overflow-x: hidden;
  }

  .hunt-header {
    align-items: flex-start;
    flex-direction: column;
    gap: 1rem;
    margin-bottom: 1.5rem;
  }

  .brand-title h1 {
    font-size: clamp(1.8rem, 10vw, 2.3rem);
  }

  .status-bar {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    width: 100%;
    min-width: 0;
    grid-gap: 0.65rem;
    gap: 0.65rem;
  }

  .status-bar .voice-toggle-btn {
    grid-column: 1 / -1;
    margin-right: 0 !important;
  }

  .stat-card {
    align-items: flex-start;
    min-width: 0;
    padding: 0.75rem;
  }

  .stat-value {
    font-size: 1rem;
    overflow-wrap: anywhere;
  }

  .hunt-grid {
    gap: 1rem;
  }

  .feeding-grounds-section,
  .war-room-section {
    min-width: 0;
    padding: 1rem;
  }

  .bounty-card {
    align-items: flex-start;
    flex-direction: column;
    gap: 1rem;
  }

  .bounty-meta {
    flex-wrap: wrap;
  }

  .bounty-action {
    width: 100%;
    text-align: left;
  }

  .cost-summary {
    align-items: flex-start;
    flex-direction: column;
    gap: 0.5rem;
  }

  .notification-toast {
    left: 0.75rem;
    right: 0.75rem;
    bottom: calc(0.75rem + env(safe-area-inset-bottom));
    padding: 0.85rem 1rem;
  }
}

/* WolfPackFeed.css - Dark Mode Viral Feed */

.wolf-feed-container {
