  align-items: center;
  gap: 10px;
}

.wolf-avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  border: 1px solid #333;
}

.wolf-username {
  color: #e0e0e0;
  font-weight: 600;
  font-size: 0.95rem;
}

.wolf-timestamp {
  color: #666;
  font-size: 0.8rem;
}

/* Content Area */
.wolf-media-container {
  width: 100%;
  background: #000;
  position: relative;
  min-height: 300px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.wolf-video {
  width: 100%;
  max-height: 600px;
  display: block;
}

.wolf-caption {
  padding: 1rem;
  color: #ccc;
  font-size: 0.95rem;
  line-height: 1.5;
}

/* Actions Bar */
.wolf-actions {
  display: flex;
  gap: 1.5rem;
  padding: 0.8rem 1rem;
