  color: #fff;
  background: #6d4aff;
}

.iv-step-1,
.iv-step-2,
.iv-step-3 {
  max-width: 1100px;
  margin: 0 auto;
  background: rgba(255, 255, 255, 0.05);
  padding: 2rem;
  border-radius: 12px;
}

.iv-creative-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(300px, 0.72fr);
  grid-gap: 1rem;
  gap: 1rem;
}

.iv-creative-brief,
.iv-scene-plan-preview {
  padding: 1.1rem;
  border: 1px solid rgba(148, 163, 184, 0.14);
  border-radius: 13px;
  background: rgba(4, 11, 22, 0.52);
}

.iv-section-heading {
  display: grid;
  grid-gap: 0.3rem;
  gap: 0.3rem;
  margin-bottom: 1rem;
}

.iv-section-heading > span {
  color: #a78bfa;
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.11em;
  text-transform: uppercase;
}

.iv-section-heading h3 {
  margin: 0;
  color: #f8fafc;
  font-size: 1rem;
}

.iv-section-heading p {
  margin: 0;
  color: #8290a7;
  font-size: 0.75rem;
  line-height: 1.5;
}

.idea-input {
  width: 100%;
  min-height: 140px;
  padding: 1rem;
  margin-bottom: 0.9rem;
  background: rgba(0, 0, 0, 0.3);
  border: 1px solid rgba(255, 255, 255, 0.1);
  color: white;
  font-size: 0.92rem;
  border-radius: 8px;
