  width: 38px;
  height: 21px;
  border-radius: 999px;
  background: rgba(148, 163, 184, 0.18);
}

.cam-setting-toggle i::after {
  position: absolute;
  top: 3px;
  left: 3px;
  width: 15px;
  height: 15px;
  border-radius: 50%;
  background: #cbd5e1;
  transition: 160ms ease;
  content: "";
}

.cam-setting-toggle input:checked + i {
  background: linear-gradient(90deg, #6d4aff, #8b5cf6);
}

.cam-setting-toggle input:checked + i::after {
  transform: translateX(17px);
  background: #fff;
}

.cam-setting-select select {
  min-width: 120px;
  min-height: 36px;
  padding: 0 9px;
  border: 1px solid rgba(148, 163, 184, 0.18);
  border-radius: 9px;
  color: #e2e8f0;
  background: #050d19;
}

.cam-workflow-strip {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  padding: 16px;
}

.cam-workflow-strip article {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 16px;
  border-right: 1px solid rgba(148, 163, 184, 0.12);
}

.cam-workflow-strip article:last-child {
  border-right: 0;
}

.cam-workflow-strip article > span {
  display: grid;
  width: 38px;
  height: 38px;
  flex: 0 0 38px;
  place-items: center;
  border-radius: 11px;
  color: #67e8f9;
  background: rgba(34, 211, 238, 0.08);
}

.cam-workflow-strip article > div {
  display: grid;
  grid-gap: 3px;
  gap: 3px;
}

.cam-workflow-strip strong {
  color: #f8fafc;
  font-size: 0.76rem;
}

.cam-workflow-strip small {
  color: #8290a7;
  font-size: 0.67rem;
  line-height: 1.4;
}

.cam-setup-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
}

@media (max-width: 900px) {
  .cam-combiner-setup-grid {
    grid-template-columns: 1fr;
  }

  .cam-workflow-strip {
    grid-template-columns: 1fr;
  }

  .cam-workflow-strip article {
    border-right: 0;
    border-bottom: 1px solid rgba(148, 163, 184, 0.12);
  }
}

@media (max-width: 620px) {
  .cam-combiner-setup {
    padding: 14px;
  }

  .cam-combiner-steps {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 12px 0;
  }

  .cam-combiner-steps li:nth-child(2)::after {
    display: none;
  }

  .cam-setup-actions {
    align-items: stretch;
    flex-direction: column-reverse;
  }
}

