/*
 * AutoPromote dashboard redesign
 *
 * This layer is intentionally scoped to `.ap-dashboard-redesign`. It changes
 * presentation only: no feature flags, API behavior, or dashboard routing.
 */

.ap-dashboard-redesign {
  --ap-bg: #050b16;
  --ap-bg-elevated: #08111f;
  --ap-surface: #0c1728;
  --ap-surface-strong: #101d31;
  --ap-surface-soft: rgba(15, 29, 50, 0.72);
  --ap-border: rgba(148, 163, 184, 0.14);
  --ap-border-strong: rgba(139, 92, 246, 0.36);
  --ap-text: #f8fafc;
  --ap-text-soft: #cbd5e1;
  --ap-muted: #8290a7;
  --ap-purple: #8b5cf6;
  --ap-purple-strong: #6d4aff;
  --ap-cyan: #22d3ee;
  --ap-green: #34d399;
  --ap-danger: #fb7185;
  --ap-shadow: 0 24px 64px rgba(0, 0, 0, 0.28);
  min-height: 100vh;
  padding-top: 72px;
  color: var(--ap-text);
  background:
    radial-gradient(circle at 24% -10%, rgba(88, 80, 236, 0.14), transparent 31rem),
    radial-gradient(circle at 88% 8%, rgba(6, 182, 212, 0.08), transparent 28rem), var(--ap-bg);
